def list_diagram_create_requests(status=None, idempotency_key=None, client_request_id=None, mermaid_sha256=None, created_at_gte=None, created_at_lte=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0294000" if __import__("os").path.isdir("./environment_mix/0294000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _ensure_audit():
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        if os.path.exists(path):
            return fname
        return None

    def _ulid_fallback():
        import random
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts_ms = int(time.time() * 1000)
        t = ts_ms & ((1 << 48) - 1)
        r = random.getrandbits(80)
        value = (t << 80) | r
        out = []
        for _ in range(26):
            out.append(alphabet[value & 31])
            value >>= 5
        return "".join(reversed(out))

    def _log_call(api_key_id, endpoint, status_s, latency_ms, error_code=None):
        fname = _ensure_audit()
        if not fname:
            return
        logs = _load(fname)
        logs.append(
            {
                "id": _ulid_fallback(),
                "api_key_id": api_key_id,
                "endpoint": endpoint,
                "status": status_s,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "timestamp": _iso(_now()),
            }
        )
        _save(fname, logs)

    t0 = time.time()

    # Validate filters
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status")

    for nm, v in [("idempotency_key", idempotency_key), ("client_request_id", client_request_id), ("mermaid_sha256", mermaid_sha256)]:
        if v is not None and not isinstance(v, str):
            _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{nm} must be a string")

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")

    gte = _parse_dt(created_at_gte) if created_at_gte is not None else None
    lte = _parse_dt(created_at_lte) if created_at_lte is not None else None
    if created_at_gte is not None and gte is None:
        _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_at_gte must be an ISO date-time string")
    if created_at_lte is not None and lte is None:
        _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_at_lte must be an ISO date-time string")

    # Ambient auth: must have an active key to list
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        _log_call(None, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is missing, invalid, or revoked")

    api_key_id = active_keys[0]["id"]

    # Pagination token: base64url of {"cursor_created_at": "...", "cursor_id": "..."}
    cursor_created_at = None
    cursor_id = None
    if page_token is not None:
        if not isinstance(page_token, str):
            _log_call(api_key_id, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_token must be a string")
        try:
            pad = "=" * (-len(page_token) % 4)
            raw = base64.urlsafe_b64decode((page_token + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            cursor_created_at = _parse_dt(obj.get("cursor_created_at"))
            cursor_id = obj.get("cursor_id")
            if cursor_created_at is None or not isinstance(cursor_id, str):
                raise ValueError("bad token")
        except Exception:
            _log_call(api_key_id, "list_diagram_create_requests", "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token")

    reqs = _load("diagram_create_requests.json")
    if not isinstance(reqs, list):
        reqs = []

    # Filter to owner
    rows = []
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != api_key_id:
            continue
        if status is not None and r.get("status") != status:
            continue
        if idempotency_key is not None and r.get("idempotency_key") != idempotency_key:
            continue
        if client_request_id is not None and r.get("client_request_id") != client_request_id:
            continue
        if mermaid_sha256 is not None and r.get("mermaid_sha256") != mermaid_sha256:
            continue
        cdt = _parse_dt(r.get("created_at"))
        if gte is not None and (cdt is None or cdt < gte):
            continue
        if lte is not None and (cdt is None or cdt > lte):
            continue
        rows.append(r)

    # Sort by created_at desc, then id desc
    def _sort_key(r):
        cdt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return (cdt, r.get("id") or "")

    rows.sort(key=_sort_key, reverse=True)

    # Apply cursor
    if cursor_created_at is not None:
        filtered = []
        for r in rows:
            cdt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            rid = r.get("id") or ""
            # since sort is desc, continue after (created_at,id) < (cursor_created_at,cursor_id)
            if (cdt < cursor_created_at) or (cdt == cursor_created_at and rid < cursor_id):
                filtered.append(r)
        rows = filtered

    total = len(rows)
    page = rows[:page_size]
    has_more = total > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_cdt = _parse_dt(last.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        tok_obj = {"cursor_created_at": _iso(last_cdt), "cursor_id": last.get("id")}
        b = json.dumps(tok_obj, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    # Optional join: attach diagram metadata for succeeded requests
    diags = _load("whimsical_diagrams.json")
    diag_by_req = {}
    if isinstance(diags, list):
        for d in diags:
            if isinstance(d, dict) and isinstance(d.get("create_request_id"), str):
                diag_by_req[d["create_request_id"]] = d

    items = []
    for r in page:
        items.append({"request": r, "diagram": diag_by_req.get(r.get("id"))})

    # Update last_used_at (authenticated request)
    now_iso = _iso(_now())
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log_call(api_key_id, "list_diagram_create_requests", "ok", (time.time() - t0) * 1000, None)
    return {"items": items, "page_size": page_size, "total": total, "has_more": has_more, "next_page_token": next_cursor}

