        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _log(api_key_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_ulid("wdc_log"),
                "api_key_id": api_key_id,
                "endpoint": "get_diagram_create_request",
                "status": status,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "timestamp": _iso(_now()),
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        _log(None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    reqs = _load("diagram_create_requests.json")
    if not isinstance(reqs, list):
        reqs = []
    diagrams = _load("whimsical_diagrams.json")
    if not isinstance(diagrams, list):
        diagrams = []

    # Find request first (do not reject based on prefix; accept any string id and look up)
    req = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == id:
            req = r
            break
    if req is None:
        _log(None, "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "diagram_create_request not found.", id=id)

    # Ambient auth: choose an active API key that owns the request
    api_key_id = req.get("api_key_id")
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            key_row = k
            break
    if key_row is None:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key for this request no longer exists.", api_key_id=api_key_id)
    if key_row.get("status") != "active":
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # Rate limit enforcement for reads (requests_per_minute_limit)
    rpm = key_row.get("requests_per_minute_limit")
    try:
        rpm = int(rpm)
    except Exception:
        rpm = None
    if rpm is None or rpm < 1 or rpm > 6000:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key has invalid rate limit configuration.", api_key_id=api_key_id)

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = _now() - datetime.timedelta(seconds=60)
    recent = 0
    for row in logs:
        if not isinstance(row, dict):
            continue
        if row.get("api_key_id") != api_key_id:
            continue
        ts = row.get("timestamp")
        try:
            if isinstance(ts, str):
                s = ts.replace("Z", "+00:00")
                dt = datetime.datetime.fromisoformat(s)
            elif isinstance(ts, datetime.datetime):
                dt = ts
            else:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rpm:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", f"Rate limit exceeded for API key ({rpm} rpm).", api_key_id=api_key_id)

    # Attach associated diagram if succeeded (or if it exists regardless)
    assoc = None
    for d in diagrams:
        if isinstance(d, dict) and d.get("create_request_id") == id:
            assoc = d
            break

    # Update last_used_at on successful authenticated request
    key_row["last_used_at"] = _iso(_now())
    key_row["updated_at"] = _iso(_now())
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    resp = {
        "request": req,
        "diagram": assoc,
    }
    _log(api_key_id, "ok", (time.time() - t0) * 1000, None)
    return resp

