        _log(api_key_id, "error", (time.time() - t0) * 1000, "INVALID_TRANSITION")
        return _err(
            "INVALID_TRANSITION",
            f"Cannot cancel request in terminal/non-cancellable state '{status}'.",
            id=id,
            from_status=status,
            to_status="cancelled",
        )

    # If a diagram already exists for this request, cancellation is invalid (request should have succeeded)
    for d in diagrams:
        if isinstance(d, dict) and d.get("create_request_id") == id:
            _log(api_key_id, "error", (time.time() - t0) * 1000, "CONFLICT")
            return _err("CONFLICT", "Cannot cancel: diagram artifact already exists for this request.", id=id)

    now = _iso(_now())
    req["status"] = "cancelled"
    req["updated_at"] = now
    req["finished_at"] = now
    # Ensure started_at exists when cancelled per constraint
    if not req.get("started_at"):
        req["started_at"] = now
    # Keep error_code/error_message null for cancelled per schema constraint
    req["error_code"] = None
    req["error_message"] = None
    # Store cancellation reason if schema doesn't have a field: place in client_request_id if empty? No.
