        rows = _load("diagram_create_requests.json")
        # minimal ULID-ish id (time-ordered enough for offline)
        rid = f"req_{int(now.timestamp()*1000)}_{hashlib.sha256((endpoint+now_iso+str(api_key_id)).encode('utf-8')).hexdigest()[:12]}"
        row = {
            "id": rid,
            "api_key_id": api_key_id,
            "title": "",
            "mermaid_markup": "",
            "mermaid_sha256": hashlib.sha256(b"").hexdigest(),
            "status": "failed" if status_code != "ok" else "succeeded",
            "idempotency_key": None,
            "client_request_id": None,
            "error_code": error_code if status_code != "ok" else None,
            "error_message": ("list call " + (error_code or "ERROR")) if status_code != "ok" else None,
            "whimsical_http_status": None,
            "attempt_count": 0,
            "started_at": now_iso,
            "finished_at": now_iso,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        rows.append(row)
        _save("diagram_create_requests.json", rows)

    # ---- validate inputs ----
    if status is not None and status not in ("active", "deleted"):
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if create_request_id is not None and not isinstance(create_request_id, str):
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "create_request_id must be a string.", field="create_request_id")
    if mermaid_sha256 is not None:
        if not isinstance(mermaid_sha256, str):
            _log(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "mermaid_sha256 must be a string.", field="mermaid_sha256")
        if not re.fullmatch(r"[0-9a-fA-F]{64}", mermaid_sha256.strip()):
            _log(None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "mermaid_sha256 must be a 64-character hex string.", field="mermaid_sha256")
        mermaid_sha256 = mermaid_sha256.lower()

    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        _log(None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.", field="page_size")

    # ---- resolve ambient authentication ----
    api_keys = _load("api_keys.json")

    def _find_usable_key():
        # No explicit credential parameter exists; choose an active key that can serve the request.
        for k in api_keys:
            if k.get("status") == "active":
                return k
        return None

    key = _find_usable_key()
    if not key:
        _log(None, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key available for this request.")

    api_key_id = key.get("id")

    # ---- enforce per-minute rate limit based on existing request log ----
    rpm_limit = key.get("requests_per_minute_limit")
    if not isinstance(rpm_limit, int) or rpm_limit < 1 or rpm_limit > 6000:
        # datastore is invalid; treat as unauthorized to avoid silent bypass
        _log(api_key_id, "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not properly configured.")

    req_log = _load("diagram_create_requests.json")
    window_start = now - datetime.timedelta(seconds=60)

    def _parse_dt(s):
        if not s: 
            return None
        try:
            if isinstance(s, str):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
        except Exception:
            return None
        return None

    recent = 0
    for r in req_log:
        if r.get("api_key_id") != api_key_id:
            continue
        ts = _parse_dt(r.get("created_at") or r.get("started_at"))
        if ts and ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts and ts >= window_start:
            recent += 1
    if recent >= rpm_limit:
        _log(api_key_id, "error", "RATE_LIMITED")
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit_per_minute=rpm_limit)

    # ---- pagination cursor ----
    cursor_created_at = None
    cursor_id = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            _log(api_key_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string.", field="page_token")
        try:
            raw = base64.urlsafe_b64decode(page_token.encode("utf-8") + b"===").decode("utf-8")
            obj = json.loads(raw)
            cursor_created_at = obj.get("created_at")
            cursor_id = obj.get("id")
        except Exception:
            _log(api_key_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token.", field="page_token")

    diagrams = _load("whimsical_diagrams.json")

    # ---- filter by ownership and parameters ----
    items = []
    for d in diagrams:
        if d.get("api_key_id") != api_key_id:
            continue
        if status is not None and d.get("status") != status:
            continue
        if create_request_id is not None and d.get("create_request_id") != create_request_id:
            continue
        if mermaid_sha256 is not None and (d.get("mermaid_sha256") or "").lower() != mermaid_sha256:
            continue
        items.append(d)

    # ---- sort created_at desc, tie-break by id desc ----
    def _sort_key(d):
        dt = _parse_dt(d.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, d.get("id") or "")

    items.sort(key=_sort_key, reverse=True)

    # ---- apply cursor (exclusive) ----
    if cursor_created_at is not None and cursor_id is not None:
        cdt = _parse_dt(cursor_created_at)
        if not cdt:
            _log(api_key_id, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid page_token cursor.", field="page_token")
        if cdt.tzinfo is None:
            cdt = cdt.replace(tzinfo=datetime.timezone.utc)

        filtered = []
        for d in items:
            dt = _parse_dt(d.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            did = d.get("id") or ""
            # since sorted desc, include items strictly "before" the cursor
            if (dt < cdt) or (dt == cdt and did < cursor_id):
                filtered.append(d)
        items = filtered

    total = len(items)
    page = items[:page_size]
    has_more = len(items) > page_size

    next_token = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        next_token = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    # ---- write last_used_at and request log ----
    # update api key last_used_at on successful authenticated request
    for k in api_keys:
        if k.get("id") == api_key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    _log(api_key_id, "ok", None)

    return {
        "data": page,
        "meta": {
            "total": total,
            "page_size": page_size,
            "has_more": has_more,
            "next_page_token": next_token,
            "filters": {
                "status": status,
                "create_request_id": create_request_id,
                "mermaid_sha256": mermaid_sha256,
            },
            "latency_ms": int((time.time() - t0) * 1000),
        },
    }

def delete_whimsical_diagram(id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0294000" if __import__("os").path.isdir("./environment_mix/0294000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return str(dt)

    def _gen_ulid(prefix):
        import os as _os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts_ms = int(time.time() * 1000)
        rand = int.from_bytes(_os.urandom(10), "big")
        val = ((ts_ms & ((1 << 48) - 1)) << 80) | rand
        out = []
        for _ in range(26):
            out.append(alphabet[val & 31])
            val >>= 5
        return f"{prefix}_{''.join(reversed(out))}"

    def _log(api_key_id, status, latency_ms, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_ulid("wdc_log"),
                "api_key_id": api_key_id,
                "endpoint": "delete_whimsical_diagram",
                "status": status,
                "error_code": error_code,
                "latency_ms": int(latency_ms),
                "timestamp": _iso(_now()),
            }
        )
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(id, str) or not id.strip():
        _log(None, "error", (time.time() - t0) * 1000, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    diagrams = _load("whimsical_diagrams.json")
    if not isinstance(diagrams, list):
        diagrams = []

    dgm_idx = None
    dgm = None
    for i, d in enumerate(diagrams):
        if isinstance(d, dict) and d.get("id") == id:
            dgm = d
            dgm_idx = i
            break
    if dgm is None:
        _log(None, "error", (time.time() - t0) * 1000, "NOT_FOUND")
        return _err("NOT_FOUND", "whimsical_diagram not found.", id=id)

    api_key_id = dgm.get("api_key_id")
    key_row = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key_id:
            key_row = k
            break
    if key_row is None:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key for this diagram no longer exists.", api_key_id=api_key_id)
    if key_row.get("status") != "active":
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is revoked.", api_key_id=api_key_id)

    # Rate limit per minute applies
    rpm = key_row.get("requests_per_minute_limit")
    try:
        rpm = int(rpm)
    except Exception:
        rpm = None
    if rpm is None or rpm < 1 or rpm > 6000:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key has invalid rate limit configuration.", api_key_id=api_key_id)

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    cutoff = _now() - datetime.timedelta(seconds=60)
    recent = 0
    for row in logs:
        if not isinstance(row, dict):
            continue
        if row.get("api_key_id") != api_key_id:
            continue
        ts = row.get("timestamp")
        try:
            if isinstance(ts, str):
                dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            elif isinstance(ts, datetime.datetime):
                dt = ts
            else:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            continue
        if dt >= cutoff:
            recent += 1
    if recent >= rpm:
        _log(api_key_id, "error", (time.time() - t0) * 1000, "RATE_LIMIT")
        return _err("RATE_LIMIT", f"Rate limit exceeded for API key ({rpm} rpm).", api_key_id=api_key_id)

    if dgm.get("status") == "deleted":
        _log(api_key_id, "error", (time.time() - t0) * 1000, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Diagram is already deleted.", id=id, from_status="deleted", to_status="deleted")
    if dgm.get("status") != "active":
        _log(api_key_id, "error", (time.time() - t0) * 1000, "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Diagram is not in an deletable state.", id=id, from_status=dgm.get("status"), to_status="deleted")

    now = _iso(_now())
    dgm["status"] = "deleted"
    dgm["updated_at"] = now
    diagrams[dgm_idx] = dgm
    _save("whimsical_diagrams.json", diagrams)

    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    _log(api_key_id, "ok", (time.time() - t0) * 1000, None)
    return {"diagram": dgm}
